import{_ as o,l as i,o as e,c as s,v as t,p as l,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"聚类标准误","description":"","frontmatter":{"title":"聚类标准误","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/clustered-se.md","filePath":"quant/clustered-se.md","lastUpdated":1789023840000}'),h={name:"quant/clustered-se.md"};function _(E,a,m,u,A,B){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="聚类标准误" tabindex="-1">聚类标准误 <a class="header-anchor" href="#聚类标准误" aria-label="Permalink to &quot;聚类标准误&quot;">​</a></h1><div class="epigraph"><p>同一家公司的多年残差、同一月份所有股票的残差，都不是独立实验；把相关关进聚类里，信息量按聚类个数来数，而不是按观测行数来数。</p><footer>—— Petersen, Estimating Standard Errors in Finance Panel Data Sets: Comparing Approaches, Review of Financial Studies, 2009</footer></div><p><a href="/quant/newey-west">Newey–West</a> 把<strong>一条</strong>时间序列的得分自相关写进长期方差。资产定价与公司金融的数据却是面板：多只股票、多个日期。只对时间做 HAC，等于假装不同股票同期独立；只对股票做稳健，等于假装同一股票跨年独立。Petersen 把金融面板里常见的低估标准误写成可对照的实验：真实相关结构一开，OLS/White 的拒绝率远超名义水平。本课缺口是把三明治的「独立观测」换成<strong>聚类</strong>：组内任意相关、组间独立。双向聚类（公司与时间）是金融默认之一，与 <a href="/quant/fama-macbeth">Fama–MacBeth</a> 是同一问题的两种算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>面板 \\(y_{it}=x_{it}^\\top\\beta+u_{it}\\)。若 \\(\\mathrm{Cov}(u_{it},u_{jt})\\neq 0\\)（同期行业、市场冲击）或 \\(\\mathrm{Cov}(u_{it},u_{i,t+k})\\neq 0\\)（公司持久未观测），得分 \\(g_{it}=x_{it}u_{it}\\) 在组内相关。把 \\(NT\\) 当样本量，标准误以 \\(\\sqrt{NT}\\) 缩小，实际上独立信息可能只有 \\(N\\) 家公司或 \\(T\\) 个月。</p><p>聚类估计把组 \\(c\\) 内的得分先加总成 \\(G_c=\\sum_{i\\in c}g_i\\)，再对 \\(\\{G_c\\}\\) 做 White：</p> \\[\\hat J=\\sum_c G_c G_c^\\top. \\]<p>组内相关形式不必指定。问题是：<strong>聚类维怎么选</strong>，以及聚类数太少时渐近以谁为准。</p><h3 id="单向还是双向" tabindex="-1">单向还是双向 <a class="header-anchor" href="#单向还是双向" aria-label="Permalink to &quot;单向还是双向&quot;">​</a></h3><p>只按公司聚类：允许公司内任意序列相关，但假定不同公司同期独立——月度截面里这条假。只按时间聚类：允许同期任意截面相关，但假定跨期独立——持久的公司效应下这条假。Petersen 与 Thompson、Cameron–Gelbach–Miller 的双向聚类把两个 \\(J\\) 相加再减去交叠项（公司–年格子），同时覆盖两种依赖。金融月度面板上，双向往往比只选一个方向更接近真实拒绝率。</p><p><span class="marginnote">聚类维应与识别假设对齐。政策按州实施，残差按州聚类；因子冲击按月到来，至少按月聚类。按「行业–年」聚类若行业数很少，名义上很稳健，实际上自由度是两位数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>实现。</strong> 多数软件的 <code>cluster</code> 是对指定 id 把得分加总。双向需要公司与时间两个 id。小样本校正（G 个聚类时乘 \\(G/(G-1)\\)）应打开。聚类数小于约 30 时，渐近 \\(z\\) 会过度拒绝，应用聚类 bootstrap 或对 \\(t\\) 用 \\(G-1\\) 自由度（Cameron–Miller 综述）。</p><p><strong>与固定效应。</strong> 公司固定效应吸收了不随时间变的组内相关的一部分，但时变的公司残差相关仍在，仍要按公司聚类。时间固定效应吸收共同冲击的水平，股票特异的同期相关（行业）仍在，仍要按时间或行业聚类。FE 与聚类不是替代，见下一课 <a href="/quant/panel-fe-finance">面板与固定效应</a>。</p><p><strong>与 Fama–MacBeth。</strong> FM 把每一期截面当一次实验，对 \\(\\{\\hat\\lambda_t\\}\\) 取时间序列标准误——本质上是按时间聚类的一种。个股特征回归里，Petersen 表明：只 FM、不处理公司内相关，仍会偏小。实务对照：双向聚类的混合 OLS、FM + 公司聚类的 \\(\\lambda_t\\) 序列、以及后课 GMM。结论只在某一种标准误下显著，应写明。</p><h3 id="聚类不能替代的东西" tabindex="-1">聚类不能替代的东西 <a class="header-anchor" href="#聚类不能替代的东西" aria-label="Permalink to &quot;聚类不能替代的东西&quot;">​</a></h3><p>聚类不管内生。按州聚类不会让反向因果消失。重叠长期收益若在同一公司多行出现，聚类能吸收一部分，但正确对象仍是重叠结构本身。极不平衡面板里，一个超大公司占 \\(G_c\\) 的大部分，聚类方差被该实体主导——应报告是否对规模加权、是否剔除。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立时每个 \\(g_{it}\\) 都是新信息。组内完全相关时，一个组只贡献一份信息，\\(G_c\\) 的方差不随组内行数下降。三明治用 \\(G_c G_c^\\top\\) 自动完成这件事：组内怎么相关都进了 \\(G_c\\) 的二次型。这就是「信息量按聚类数数」的机制。</p><p>双向的机制是 Bonferroni 式的并：公司内链与时间内链都允许，再减掉格子被算两次的对角。它仍要求<strong>不同公司在不同时间的残差</strong>不要有尚未被 \\(x\\) 吸收的共同结构——例如所有公司共享一个未被回归元抓住的长期制度。那种情况需要更厚的 HAC、因子、或把标准误再加一层。</p><p><span class="marginnote">「聚类让标准误变大」不是定理。若组内相关为负（超常收益后的反转被重复计算），聚类标准误可以变小。应看经济上相关该是正是负，而不是把变大当成稳健的充分统计。</span></p><h3 id="多维与过细" tabindex="-1">多维与过细 <a class="header-anchor" href="#多维与过细" aria-label="Permalink to &quot;多维与过细&quot;">​</a></h3><p>可以按「公司 × 交易所」聚，若这才是独立实验的边界。过细（按公司–日）等于回到 White。过粗（按十年一个体制）只剩几个聚类，估计的是那几个块的方差，不是 \\(\\beta\\)。先写清随机性来自哪一维：抽样公司、抽样年份，还是抽样市场冲击。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(T=12\\) 的短面板按时间聚类没有渐近。IPO、退市导致的非平衡会让晚期月份的 \\(G_t\\) 更吵。国际面板按国家聚类，国家数往往太少。高频面板不要按毫秒当时间聚类——应对齐到事件或分钟，否则 \\(T\\) 虚高。</p><p>工程默认：公司金融年度面板按公司聚类；资产定价月度个股按公司与月双向；组合对因子的时间序列则 Newey–West 即可，不必「再按组合聚类」。不要用聚类去掩盖只有 15 个事件的事件研究。不要在同一张表为每个系数挑选使 \\(t\\) 最大的聚类维。</p>',26)),(e(),l(d,null,{default:r(()=>[p(n,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%9D%A2%E6%9D%BF%E6%AE%8B%E5%B7%AE%20u_it%22%5D%20--%3E%20FIRM%5B%22%E6%8C%89%E5%85%AC%E5%8F%B8%E5%8A%A0%E6%80%BB%E5%BE%97%E5%88%86%22%5D%0A%20%20P%20--%3E%20TIME%5B%22%E6%8C%89%E6%9C%88%E4%BB%BD%E5%8A%A0%E6%80%BB%E5%BE%97%E5%88%86%22%5D%0A%20%20FIRM%20--%3E%20J1%5B%22J_firm%22%5D%0A%20%20TIME%20--%3E%20J2%5B%22J_time%22%5D%0A%20%20J1%20--%3E%20TWO%5B%22%E5%8F%8C%E5%90%91%3A%20J1%2BJ2-%E4%BA%A4%E5%8F%A0%22%5D%0A%20%20J2%20--%3E%20TWO%0A%20%20TWO%20--%3E%20SE%5B%22%E8%81%9A%E7%B1%BB%E6%A0%87%E5%87%86%E8%AF%AF%22%5D%0A%20%20TWO%20--%3E%20N%5B%22%E6%9C%89%E6%95%88%E4%BF%A1%E6%81%AF%20%E2%89%88%20%E8%81%9A%E7%B1%BB%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金融面板的独立信息通常按公司数或月数计，不按 \\(NT\\) 计。</li><li>聚类把组内相关关进加总得分；双向聚类同时覆盖公司内持续与同期截面相关。</li><li>聚类数太少则渐近失效，应改 bootstrap 或更粗的检验。</li><li>与 FM、FE、HAC 分工：同一依赖结构的不同写法，不是层层叠加的护身符。</li><li>出处：Petersen, <em>Review of Financial Studies</em>, 2009；双向见 Thompson, <em>Journal of Financial Economics</em>, 2011，以及 Cameron, Gelbach and Miller, <em>Journal of Business &amp; Economic Statistics</em>, 2011。</li></ul>',2))])}const b=o(h,[["render",_]]);export{T as __pageData,b as default};
